import json

def solve():
    houses = [1, 2, 3, 4, 5, 6]

    # Attributes as specified in the puzzle
    Names = ["Carol", "Bob", "Alice", "Arnold", "Eric", "Peter"]
    Phones = ["samsung galaxy s21", "google pixel 6", "iphone 13", "huawei p50", "oneplus 9", "xiaomi mi 11"]
    Nationalities = ["swede", "chinese", "norwegian", "dane", "german", "brit"]
    Colors = ["blue", "red", "yellow", "green", "white", "purple"]

    groups = {
        "Name": Names,
        "phone models": Phones,
        "nationalities": Nationalities,
        "favorite color": Colors
    }

    # Variables are tuples (group_name, value)
    vars_list = []
    for gname, values in groups.items():
        for v in values:
            vars_list.append((gname, v))

    # Initial domain restrictions (unary)
    all_houses = set(houses)
    domain_restrictions = {}

    # From clues
    # 1. Carol is not in the third house.
    domain_restrictions[("Name", "Carol")] = all_houses - {3}
    # 7. The person who uses a Huawei P50 is not in the third house.
    domain_restrictions[("phone models", "huawei p50")] = all_houses - {3}
    # 8. The person who uses a Samsung Galaxy S21 is in the fifth house.
    domain_restrictions[("phone models", "samsung galaxy s21")] = {5}
    # 15. S21 is directly left of iPhone 13 implies iPhone 13 cannot be in 1
    domain_restrictions[("phone models", "iphone 13")] = all_houses - {1}
    # 4. Arnold is directly left of Alice: Arnold cannot be in 6; Alice cannot be in 1
    domain_restrictions[("Name", "Arnold")] = all_houses - {6}
    domain_restrictions[("Name", "Alice")] = all_houses - {1}

    # Equalities (varA == varB)
    equalities = [
        (("Name", "Carol"), ("favorite color", "green")),                      # 3
        (("Name", "Alice"), ("nationalities", "german")),                      # 5
        (("phone models", "oneplus 9"), ("favorite color", "purple")),         # 6
        (("nationalities", "norwegian"), ("favorite color", "purple")),        # 16
        (("phone models", "xiaomi mi 11"), ("nationalities", "chinese")),      # 17
        (("favorite color", "blue"), ("Name", "Peter")),                       # 13
        (("Name", "Peter"), ("nationalities", "brit")),                        # 14
        (("phone models", "samsung galaxy s21"), ("Name", "Bob")),             # 10
    ]

    # Adjacency (varA + 1 == varB)
    adjacency = [
        (("Name", "Arnold"), ("Name", "Alice")),                               # 4
        (("phone models", "samsung galaxy s21"), ("phone models", "iphone 13"))# 15
    ]

    # Less-than (varA < varB)
    less_than = [
        (("phone models", "samsung galaxy s21"), ("Name", "Peter")),           # 12
    ]

    # Greater-than (varA > varB)
    greater_than = [
        (("favorite color", "white"), ("favorite color", "red")),              # 9
    ]

    # Absolute difference 2 (|varA - varB| == 2)
    diff_two = [
        (("nationalities", "dane"), ("nationalities", "brit")),                # 2
    ]

    # Not-equal to house constraints
    not_equal_house = [
        (("Name", "Carol"), 3),                                                # 1
        (("phone models", "huawei p50"), 3),                                   # 7
    ]

    # Helper structures for assignment
    assigned = {var: None for var in vars_list}
    used_in_group = {g: set() for g in groups.keys()}

    # Fast lookup helpers
    def get(var):
        return assigned[var]

    def group_of(var):
        return var[0]

    # Compute dynamic domain for variable var given current partial assignment
    def get_domain(var):
        g, v = var
        # Start with base domain (all houses minus those used in this group)
        if var in domain_restrictions:
            domain = set(domain_restrictions[var])
        else:
            domain = set(all_houses)
        # Remove used houses in the same group (AllDifferent per group)
        domain -= used_in_group[g]

        # Apply equality constraints if counterpart assigned
        for (a, b) in equalities:
            if var == a:
                hb = get(b)
                if hb is not None:
                    domain &= {hb}
            elif var == b:
                ha = get(a)
                if ha is not None:
                    domain &= {ha}

        # Apply adjacency constraints refinement
        for (a, b) in adjacency:
            if var == a:
                # a + 1 == b => a cannot be 6
                domain -= {6}
                hb = get(b)
                if hb is not None:
                    domain &= {hb - 1}
            elif var == b:
                # a + 1 == b => b cannot be 1
                domain -= {1}
                ha = get(a)
                if ha is not None:
                    domain &= {ha + 1}

        # Apply less-than constraints refinement
        for (a, b) in less_than:
            if var == a:
                hb = get(b)
                if hb is not None:
                    domain &= set(h for h in domain if h < hb)
            elif var == b:
                ha = get(a)
                if ha is not None:
                    domain &= set(h for h in domain if h > ha)

        # Apply greater-than constraints refinement
        for (a, b) in greater_than:
            if var == a:
                hb = get(b)
                if hb is not None:
                    domain &= set(h for h in domain if h > hb)
            elif var == b:
                ha = get(a)
                if ha is not None:
                    domain &= set(h for h in domain if h < ha)

        # Apply diff-two constraints refinement
        for (a, b) in diff_two:
            if var == a:
                hb = get(b)
                if hb is not None:
                    domain &= set(h for h in domain if abs(h - hb) == 2)
            elif var == b:
                ha = get(a)
                if ha is not None:
                    domain &= set(h for h in domain if abs(h - ha) == 2)

        # Apply not-equal-to-house constraints
        for (a, house) in not_equal_house:
            if var == a:
                domain -= {house}

        return sorted(domain)

    # Check if current partial assignment satisfies all constraints so far
    def check_constraints():
        # AllDifferent per group enforced by used_in_group; no further check needed

        # 1. Carol is not in the third house.
        h = get(("Name", "Carol"))
        if h == 3:
            return False

        # 2. There is one house between the Dane and the British person.
        hd = get(("nationalities", "dane"))
        hb = get(("nationalities", "brit"))
        if hd is not None and hb is not None:
            if abs(hd - hb) != 2:
                return False

        # 3. Carol is the person whose favorite color is green.
        hc = get(("Name", "Carol"))
        hg = get(("favorite color", "green"))
        if hc is not None and hg is not None and hc != hg:
            return False

        # 4. Arnold is directly left of Alice.
        ha = get(("Name", "Arnold"))
        hl = get(("Name", "Alice"))
        if ha is not None and ha == 6:
            return False
        if hl is not None and hl == 1:
            return False
        if ha is not None and hl is not None and ha + 1 != hl:
            return False

        # 5. Alice is the German.
        hAlice = get(("Name", "Alice"))
        hGerman = get(("nationalities", "german"))
        if hAlice is not None and hGerman is not None and hAlice != hGerman:
            return False

        # 6. OnePlus 9 user loves purple.
        hOP = get(("phone models", "oneplus 9"))
        hPurple = get(("favorite color", "purple"))
        if hOP is not None and hPurple is not None and hOP != hPurple:
            return False

        # 7. Huawei P50 not in house 3.
        hH = get(("phone models", "huawei p50"))
        if hH == 3:
            return False

        # 8. SG S21 is in the fifth house.
        hS = get(("phone models", "samsung galaxy s21"))
        if hS is not None and hS != 5:
            return False

        # 9. White to the right of red.
        hW = get(("favorite color", "white"))
        hR = get(("favorite color", "red"))
        if hW is not None and hR is not None and not (hW > hR):
            return False

        # 10. SG S21 is Bob.
        hBob = get(("Name", "Bob"))
        if hS is not None and hBob is not None and hS != hBob:
            return False

        # 11. Dane loves yellow.
        hDane = get(("nationalities", "dane"))
        hYellow = get(("favorite color", "yellow"))
        if hDane is not None and hYellow is not None and hDane != hYellow:
            return False

        # 12. SG S21 is somewhere to the left of Peter.
        hPeter = get(("Name", "Peter"))
        if hS is not None and hPeter is not None and not (hS < hPeter):
            return False

        # 13. Blue is Peter.
        hBlue = get(("favorite color", "blue"))
        if hBlue is not None and hPeter is not None and hBlue != hPeter:
            return False

        # 14. Peter is the British person.
        hBrit = get(("nationalities", "brit"))
        if hPeter is not None and hBrit is not None and hPeter != hBrit:
            return False

        # 15. S21 is directly left of iPhone 13.
        hIP = get(("phone models", "iphone 13"))
        if hS is not None and hS == 6:
            return False
        if hIP is not None and hIP == 1:
            return False
        if hS is not None and hIP is not None and hS + 1 != hIP:
            return False

        # 16. Norwegian is purple.
        hNor = get(("nationalities", "norwegian"))
        if hNor is not None and hPurple is not None and hNor != hPurple:
            return False

        # 17. Xiaomi Mi 11 is the Chinese.
        hX = get(("phone models", "xiaomi mi 11"))
        hChi = get(("nationalities", "chinese"))
        if hX is not None and hChi is not None and hX != hChi:
            return False

        return True

    # Backtracking solver
    def select_unassigned_variable():
        unassigned = [var for var in vars_list if assigned[var] is None]
        # MRV heuristic: choose variable with smallest domain
        best_var = None
        best_domain = None
        best_len = 10**9
        for var in unassigned:
            dom = get_domain(var)
            l = len(dom)
            if l < best_len:
                best_len = l
                best_var = var
                best_domain = dom
            if best_len == 1:
                break
        return best_var, best_domain if best_domain is not None else []

    def backtrack():
        if all(assigned[var] is not None for var in vars_list):
            return True
        var, domain = select_unassigned_variable()
        if var is None:
            return False
        g, v = var
        for h in domain:
            # Assign if house not used in this group (already ensured by domain)
            assigned[var] = h
            used_in_group[g].add(h)

            if check_constraints():
                if backtrack():
                    return True

            # Undo
            assigned[var] = None
            used_in_group[g].remove(h)
        return False

    # Run the solver
    solved = backtrack()
    if not solved:
        raise RuntimeError("No solution found")

    # Build the solution rows by house
    house_to_name = {}
    for name in Names:
        house_to_name[assigned[("Name", name)]] = name
    house_to_phone = {}
    for phone in Phones:
        house_to_phone[assigned[("phone models", phone)]] = phone
    house_to_nat = {}
    for nat in Nationalities:
        house_to_nat[assigned[("nationalities", nat)]] = nat
    house_to_color = {}
    for color in Colors:
        house_to_color[assigned[("favorite color", color)]] = color

    header = ["House", "Name", "phone models", "nationalities", "favorite color"]
    rows = []
    for h in houses:
        row = [
            str(h),
            house_to_name[h],
            house_to_phone[h],
            house_to_nat[h],
            house_to_color[h],
        ]
        rows.append(row)

    result = {
        "solution": {
            "header": header,
            "rows": rows
        }
    }
    print(json.dumps(result, ensure_ascii=False, indent=2))

if __name__ == "__main__":
    solve()
